class Counter {
    private int value;

    Counter(int start) {
        this.value = start;
    }

    void increment() {
        value++;
    }

    int getValue() {
        return value;
    }
}

public class Main {
    public static void main(String[] args) {
        Counter counter = new Counter(4);
        counter.increment();
        System.out.println("Value: " + counter.getValue());
    }
}

