#include <stdio.h>

typedef struct {
    const char *name;
    int credits;
} Course;

int main(void) {
    Course course = {"C Basics", 3};
    FILE *file = fopen("course.txt", "w");
    if (file == NULL) {
        perror("course.txt");
        return 1;
    }
    if (fprintf(file, "%s: %d credits\n", course.name, course.credits) < 0) {
        fclose(file);
        return 1;
    }
    if (fclose(file) != 0) {
        return 1;
    }
    printf("Wrote %s (%d credits)\n", course.name, course.credits);
    return 0;
}

