#include <iostream>

class Counter {
private:
    int value;
public:
    explicit Counter(int start) : value(start) {}
    void increment() { ++value; }
    int getValue() const { return value; }
};

int main() {
    Counter counter(4);
    counter.increment();
    std::cout << "Value: " << counter.getValue() << '\n';
    return 0;
}

#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    std::vector<int> values{4, 1, 3, 2};
    std::sort(values.begin(), values.end());
    int sum = std::accumulate(values.begin(), values.end(), 0);
    for (int value : values) {
        std::cout << value << ' ';
    }
    std::cout << "| sum: " << sum << '\n';
    return 0;
}

